def transform(grid):
    n = len(grid)
    top_rows = [r for i, r in enumerate(grid[:n//2])]
    # find separator: rows are top half, one separator row (uniform), bottom half
    # top = first n//2 rows... actually find the uniform row
    sep_idx = None
    for i, r in enumerate(grid):
        if len(set(r)) == 1 and len(set(grid[j][0] for j in range(len(grid)))) > 1:
            if i > 0 and i < len(grid)-1 and len(set(grid[i-1])) > 1:
                pass
    # simpler: separator is the row whose single value differs from neighbors
    for i, r in enumerate(grid):
        if len(set(r)) == 1:
            if (i == 0 or len(set(grid[i-1])) > 1) and len(set(grid[i+1])) > 1:
                sep_idx = i
                break
    top = grid[:sep_idx]
    bottom = grid[sep_idx+1:]
    out = []
    for tr, br in zip(top, bottom):
        out.append([3 if a == b else 4 for a, b in zip(tr, br)])
    return out
